{
  "columns": [
    "Paper",
    "Anomaly Detection Method",
    "Dataset",
    "Evaluation Metrics",
    "Key Findings"
  ],
  "rows": [
    {
      "Paper": "P06",
      "Anomaly Detection Method": "Anomaly Transformer using an Anomaly-Attention mechanism with a two-branch structure: prior-association from a learnable Gaussian kernel and series-association from self-attention weights. A minimax optimization strategy amplifies the Association Discrepancy, which is used as an association-based anomaly criterion.",
      "Dataset": "Reported on six benchmarks covering three real-world applications; in the provided context, SWaT and UCR (250 univariate sub-datasets) are explicitly mentioned. Full benchmark names are not listed in the provided context.",
      "Evaluation Metrics": "Precision, Recall, and F1-score (%) are reported for the UCR dataset.",
      "Key Findings": "On UCR, Anomaly Transformer achieves P=72.80, R=99.60, F1=84.12, outperforming baselines such as Isolation Forest, LSTM-VAE, and others. It is reported as state-of-the-art on six benchmarks, and on SWaT it can detect anomalies at an early stage."
    },
    {
      "Paper": "P07",
      "Anomaly Detection Method": "TranAD: a reconstruction-based model that learns broad-level trends from training data. It normalizes time-series data, converts them to sliding windows, predicts anomaly scores by reconstructing input windows, and applies a threshold computed from past anomaly scores for detection. It also supports anomaly diagnosis by indicating which modes are anomalous.",
      "Dataset": "Not explicitly specified in the provided context.",
      "Evaluation Metrics": "Not explicitly specified in the provided context.",
      "Key Findings": "No specific quantitative results are provided in the context. The paper states that TranAD aims to improve anomaly detection and diagnosis performance while reducing training times compared with reconstruction-based and recurrent methods."
    },
    {
      "Paper": "P08",
      "Anomaly Detection Method": "DCdetector: uses dual patch-wise and in-patch branches with stop-gradient modules. The point-wise anomaly score is computed as the sum of KL divergences between representations from different views: KL(P, Stopgrad(N)) + KL(N, Stopgrad(P)). It uses instance normalization for preprocessing and applies a threshold to determine anomalies.",
      "Dataset": "Eight benchmarks: MSL, SMAP, PSM, SMD, SWaT, NIPS-TS-SWAN, NIPS-TS-GECCO, and UCR (250 univariate sub-datasets).",
      "Evaluation Metrics": "Not explicitly named in the provided context; reports multi-metrics comparisons and counts of sub-datasets reaching state-of-the-art.",
      "Key Findings": "DCdetector achieves state-of-the-art results on NIPS-TS-GECCO even with a 1.1% anomaly ratio and outperforms Anomaly Transformer in most metrics. On univariate UCR data, it correctly identifies and locates single subsequence anomalies. Ablation studies show that using two stop-gradient modules gives the best performance, and only instance normalization is used in the final model."
    }
  ]
}

