output.comparison:
{
  "columns": ["Paper", "Attention Mechanism", "Key Components", "Design Differences", "Computational Complexity"],
  "rows": [
    {
      "Paper": "P06 (Anomaly Transformer)",
      "Attention Mechanism": "Anomaly-Attention: a two-branch self-attention that models prior-association via a learnable Gaussian kernel and series-association via scaled dot-product self-attention.",
      "Key Components": "Learnable Gaussian kernel with scale sigma; prior-association matrix P^l from temporal distance; series-association matrix S^l = Softmax(QK^T/sqrt(d_model)); reconstruction Z^l = S^l V; minimax strategy with stop-gradient to amplify association discrepancy.",
      "Design Differences": "Uses a two-branch attention inside a single self-attention module to contrast adjacent-concentration priors with learned raw-series associations; relies on minimax training and association discrepancy as anomaly criterion. Unlike P08, it uses a Gaussian kernel and reconstruction loss; unlike P09, it does not use graph attention layers.",
      "Computational Complexity": "Not explicitly stated in the provided context. The attention map is N x N from QK^T (sequence length N), suggesting quadratic complexity in N."
    },
    {
      "Paper": "P08 (DCdetector)",
      "Attention Mechanism": "Dual Attention Contrastive Structure: patch-wise multi-head self-attention and in-patch multi-head self-attention with shared weights, used to learn two permutation-invariant views and their representation discrepancy.",
      "Key Components": "Channel independence + patching; patch-wise attention (dependencies among patches); in-patch attention (dependencies of points within a patch); shared W_Q and W_K across the two branches; multi-scale patching; upsampling to align representations; contrastive discrepancy loss; no Gaussian kernel, minimax strategy, or reconstruction loss.",
      "Design Differences": "Uses a dual-branch attention over patched time series (patch-wise vs in-patch) with shared weights and contrastive discrepancy, instead of P06's prior/series association with Gaussian kernel and minimax. Unlike P09, it does not use graph attention or explicit feature-level/time-level graph modeling; it applies channel-independent patching and multi-scale attention.",
      "Computational Complexity": "Not expressed in asymptotic form in the provided context. Ablations show memory/time trade-offs: d_model=128 uses about 3.9 GB and 0.05 s; d_model=256 uses about 6.1 GB and 0.10 s; d_model=1024 uses about 18.4 GB and 0.92 s. The chosen d_model=256 balances performance and complexity; best performance is achieved with small attention head numbers."
    },
    {
      "Paper": "P09 (graph attention-based method)",
      "Attention Mechanism": "Two parallel graph attention layers: feature-oriented graph attention layer and time-oriented graph attention layer.",
      "Key Components": "Feature-oriented graph attention captures causal relationships between multiple features; time-oriented graph attention captures dependencies along the temporal dimension; jointly trained forecasting-based and reconstruction-based models with a joint objective function; interpretable attention scores for anomaly diagnosis.",
      "Design Differences": "Uses graph attention networks to learn dynamic relationships among features and timestamps, emphasizing inter-feature causality and temporal dependencies. Unlike P06, no Gaussian-kernel prior-association; unlike P08, no patch-wise/in-patch dual attention or channel-independent patching; integrates forecasting and reconstruction objectives jointly.",
      "Computational Complexity": "Not specified in the provided context."
    }
  ]
}

